insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010001', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Qual é o domínio real de $f(x)=\sqrt{4-x}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100011', '40000000-0000-4000-8000-000000010001', 'A', '$x\le4$', 1), ('50000000-0000-4000-8000-000000100012', '40000000-0000-4000-8000-000000010001', 'B', '$x<4$', 2), ('50000000-0000-4000-8000-000000100013', '40000000-0000-4000-8000-000000010001', 'C', '$x\ge4$', 3), ('50000000-0000-4000-8000-000000100014', '40000000-0000-4000-8000-000000010001', 'D', 'Todos os números reais', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010001', '50000000-0000-4000-8000-000000100011') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010001', '30000000-0000-4000-8000-000000000012', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100011', '40000000-0000-4000-8000-000000010001', 'Em uma raiz quadrada real, o radicando não pode ser negativo.', 1), ('60000000-0000-4000-8000-000000100012', '40000000-0000-4000-8000-000000010001', 'Resolva a desigualdade $4-x\ge0$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010001', '$(-\infty,4]$', 'A raiz quadrada representa um número real apenas quando seu radicando é não negativo. A condição vem da expressão dentro da raiz, e o valor que zera o radicando também é permitido.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100011', '40000000-0000-4000-8000-000000010001', 'Observe a restrição', 'Precisamos de $4-x\ge0$ para que $\sqrt{4-x}$ exista nos reais.', 1), ('70000000-0000-4000-8000-000000100012', '40000000-0000-4000-8000-000000010001', 'Isole $x$', 'Somando $x$ aos dois lados, obtemos $4\ge x$, ou $x\le4$.', 2), ('70000000-0000-4000-8000-000000100013', '40000000-0000-4000-8000-000000010001', 'Inclua o extremo', 'Em $x=4$, a raiz vale $0$, que é real. Portanto $4$ pertence ao domínio.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010002', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Se $f(x)=3x-1$ e $g(x)=x^2+1$, qual é o valor de $(f\circ g)(2)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100021', '40000000-0000-4000-8000-000000010002', 'A', '$14$', 1), ('50000000-0000-4000-8000-000000100022', '40000000-0000-4000-8000-000000010002', 'B', '$12$', 2), ('50000000-0000-4000-8000-000000100023', '40000000-0000-4000-8000-000000010002', 'C', '$8$', 3), ('50000000-0000-4000-8000-000000100024', '40000000-0000-4000-8000-000000010002', 'D', '$6$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010002', '50000000-0000-4000-8000-000000100021') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010002', '30000000-0000-4000-8000-000000000014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100021', '40000000-0000-4000-8000-000000010002', 'A composição $f\circ g$ manda primeiro o valor para $g$.', 1), ('60000000-0000-4000-8000-000000100022', '40000000-0000-4000-8000-000000010002', 'Calcule $g(2)$ antes de usar a fórmula de $f$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010002', '$14$', 'Na composição indicada, a saída de $g$ se torna a entrada de $f$. Trocar a ordem das funções é um erro comum e leva a outro resultado.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100021', '40000000-0000-4000-8000-000000010002', 'Comece pela função interna', '$g(2)=2^2+1=5$.', 1), ('70000000-0000-4000-8000-000000100022', '40000000-0000-4000-8000-000000010002', 'Use a saída em $f$', '$f(5)=3\cdot5-1$.', 2), ('70000000-0000-4000-8000-000000100023', '40000000-0000-4000-8000-000000010002', 'Conclua', '$15-1=14$, portanto $(f\circ g)(2)=14$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010003', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Para $f(x)=2x-5$, qual é o valor de $f^{-1}(7)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100031', '40000000-0000-4000-8000-000000010003', 'A', '$6$', 1), ('50000000-0000-4000-8000-000000100032', '40000000-0000-4000-8000-000000010003', 'B', '$1$', 2), ('50000000-0000-4000-8000-000000100033', '40000000-0000-4000-8000-000000010003', 'C', '$9$', 3), ('50000000-0000-4000-8000-000000100034', '40000000-0000-4000-8000-000000010003', 'D', '$12$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010003', '50000000-0000-4000-8000-000000100031') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010003', '30000000-0000-4000-8000-000000000015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100031', '40000000-0000-4000-8000-000000010003', 'A inversa desfaz o que a função original faz.', 1), ('60000000-0000-4000-8000-000000100032', '40000000-0000-4000-8000-000000010003', 'Procure o número $x$ para o qual $2x-5=7$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010003', '$6$', 'Encontrar $f^{-1}(7)$ significa descobrir qual entrada produz saída $7$ na função original. Não significa calcular o recíproco de $f(7)$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100031', '40000000-0000-4000-8000-000000010003', 'Traduza a inversa', 'Escrevemos $f(x)=7$, isto é, $2x-5=7$.', 1), ('70000000-0000-4000-8000-000000100032', '40000000-0000-4000-8000-000000010003', 'Resolva a equação', 'Somando $5$, resulta $2x=12$; dividindo por $2$, resulta $x=6$.', 2), ('70000000-0000-4000-8000-000000100033', '40000000-0000-4000-8000-000000010003', 'Verifique', '$f(6)=12-5=7$, então $f^{-1}(7)=6$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010004', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Resolva a equação $e^{2x}=e^6$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100041', '40000000-0000-4000-8000-000000010004', 'A', '$x=3$', 1), ('50000000-0000-4000-8000-000000100042', '40000000-0000-4000-8000-000000010004', 'B', '$x=12$', 2), ('50000000-0000-4000-8000-000000100043', '40000000-0000-4000-8000-000000010004', 'C', '$x=4$', 3), ('50000000-0000-4000-8000-000000100044', '40000000-0000-4000-8000-000000010004', 'D', '$x=6$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010004', '50000000-0000-4000-8000-000000100041') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010004', '30000000-0000-4000-8000-000000000013', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100041', '40000000-0000-4000-8000-000000010004', 'A função exponencial de base $e$ é injetiva.', 1), ('60000000-0000-4000-8000-000000100042', '40000000-0000-4000-8000-000000010004', 'Se as bases são iguais, compare os expoentes.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010004', '$x=3$', 'Como ambos os lados têm a mesma base positiva e diferente de $1$, a igualdade das potências implica igualdade dos expoentes.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100041', '40000000-0000-4000-8000-000000010004', 'Compare as potências', 'Temos $e^{2x}=e^6$ com a mesma base $e$.', 1), ('70000000-0000-4000-8000-000000100042', '40000000-0000-4000-8000-000000010004', 'Iguale os expoentes', 'Logo $2x=6$.', 2), ('70000000-0000-4000-8000-000000100043', '40000000-0000-4000-8000-000000010004', 'Resolva', 'Dividindo por $2$, encontramos $x=3$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010005', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'O gráfico de $g(x)=f(x-2)+3$ é obtido a partir do gráfico de $f$. Qual transformação é correta?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100051', '40000000-0000-4000-8000-000000010005', 'A', '2 unidades à direita e 3 para cima', 1), ('50000000-0000-4000-8000-000000100052', '40000000-0000-4000-8000-000000010005', 'B', '2 unidades à esquerda e 3 para cima', 2), ('50000000-0000-4000-8000-000000100053', '40000000-0000-4000-8000-000000010005', 'C', '2 unidades à direita e 3 para baixo', 3), ('50000000-0000-4000-8000-000000100054', '40000000-0000-4000-8000-000000010005', 'D', 'Uma dilatação vertical de fator 3', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010005', '50000000-0000-4000-8000-000000100051') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010005', '30000000-0000-4000-8000-000000000014', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100051', '40000000-0000-4000-8000-000000010005', 'Alterações dentro do argumento afetam o eixo horizontal.', 1), ('60000000-0000-4000-8000-000000100052', '40000000-0000-4000-8000-000000010005', 'Em $f(x-a)$, o gráfico se desloca na direção oposta ao sinal visível.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010005', '2 unidades à direita e 3 para cima.', 'O termo $x-2$ faz cada valor que antes aparecia em $x$ surgir agora em $x+2$, deslocando o desenho para a direita. O $+3$ externo soma três a cada altura.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100051', '40000000-0000-4000-8000-000000010005', 'Leia a transformação horizontal', 'A expressão $f(x-2)$ desloca o gráfico de $f$ em $2$ unidades para a direita.', 1), ('70000000-0000-4000-8000-000000100052', '40000000-0000-4000-8000-000000010005', 'Leia a transformação vertical', 'O termo externo $+3$ acrescenta $3$ a todo valor de saída.', 2), ('70000000-0000-4000-8000-000000100053', '40000000-0000-4000-8000-000000010005', 'Combine os efeitos', 'O resultado é direita $2$ e cima $3$, sem dilatação.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010006', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Resolva $\log_2(x-1)=3$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100061', '40000000-0000-4000-8000-000000010006', 'A', '$x=9$', 1), ('50000000-0000-4000-8000-000000100062', '40000000-0000-4000-8000-000000010006', 'B', '$x=8$', 2), ('50000000-0000-4000-8000-000000100063', '40000000-0000-4000-8000-000000010006', 'C', '$x=7$', 3), ('50000000-0000-4000-8000-000000100064', '40000000-0000-4000-8000-000000010006', 'D', '$x=4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010006', '50000000-0000-4000-8000-000000100061') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010006', '30000000-0000-4000-8000-000000000015', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100061', '40000000-0000-4000-8000-000000010006', 'Transforme a igualdade logarítmica em uma igualdade exponencial.', 1), ('60000000-0000-4000-8000-000000100062', '40000000-0000-4000-8000-000000010006', 'Depois de obter $x-1$, lembre-se de recuperar $x$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010006', '$x=9$', 'O logaritmo informa o expoente necessário para produzir o argumento. Além de resolver a equação, é preciso respeitar a condição $x-1>0$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100061', '40000000-0000-4000-8000-000000010006', 'Converta a forma', '$\log_2(x-1)=3$ equivale a $x-1=2^3$.', 1), ('70000000-0000-4000-8000-000000100062', '40000000-0000-4000-8000-000000010006', 'Calcule a potência', '$2^3=8$, então $x-1=8$.', 2), ('70000000-0000-4000-8000-000000100063', '40000000-0000-4000-8000-000000010006', 'Recupere a variável', 'Somando $1$, obtemos $x=9$, que satisfaz $x>1$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010007', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Calcule $\lim_{x\to3}\frac{x^2-9}{x-3}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100071', '40000000-0000-4000-8000-000000010007', 'A', '$6$', 1), ('50000000-0000-4000-8000-000000100072', '40000000-0000-4000-8000-000000010007', 'B', '$0$', 2), ('50000000-0000-4000-8000-000000100073', '40000000-0000-4000-8000-000000010007', 'C', '$3$', 3), ('50000000-0000-4000-8000-000000100074', '40000000-0000-4000-8000-000000010007', 'D', 'O limite não existe', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010007', '50000000-0000-4000-8000-000000100071') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010007', '30000000-0000-4000-8000-000000000017', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100071', '40000000-0000-4000-8000-000000010007', 'A substituição direta dá uma forma $0/0$; isso pede simplificação.', 1), ('60000000-0000-4000-8000-000000100072', '40000000-0000-4000-8000-000000010007', 'Fatore $x^2-9$ como diferença de quadrados.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010007', '$6$', 'Embora a expressão original não esteja definida em $x=3$, o limite depende dos valores próximos de $3$. Após cancelar o fator que causa o zero no denominador, a tendência fica visível.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100071', '40000000-0000-4000-8000-000000010007', 'Fatore o numerador', '$x^2-9=(x-3)(x+3)$.', 1), ('70000000-0000-4000-8000-000000100072', '40000000-0000-4000-8000-000000010007', 'Simplifique perto de $3$', 'Para $x\ne3$, a fração é igual a $x+3$.', 2), ('70000000-0000-4000-8000-000000100073', '40000000-0000-4000-8000-000000010007', 'Avalie a tendência', 'Quando $x$ tende a $3$, $x+3$ tende a $6$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010008', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $\lim_{x\to5}\frac{\sqrt{x+4}-3}{x-5}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100081', '40000000-0000-4000-8000-000000010008', 'A', '$1/6$', 1), ('50000000-0000-4000-8000-000000100082', '40000000-0000-4000-8000-000000010008', 'B', '$1/3$', 2), ('50000000-0000-4000-8000-000000100083', '40000000-0000-4000-8000-000000010008', 'C', '$6$', 3), ('50000000-0000-4000-8000-000000100084', '40000000-0000-4000-8000-000000010008', 'D', '$0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010008', '50000000-0000-4000-8000-000000100081') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010008', '30000000-0000-4000-8000-000000000018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100081', '40000000-0000-4000-8000-000000010008', 'A forma inicial é $0/0$; procure uma expressão conjugada.', 1), ('60000000-0000-4000-8000-000000100082', '40000000-0000-4000-8000-000000010008', 'Multiplique numerador e denominador por $\sqrt{x+4}+3$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010008', '$1/6$', 'A racionalização elimina a raiz da diferença no numerador. Só depois dessa simplificação é seguro substituir $x=5$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100081', '40000000-0000-4000-8000-000000010008', 'Escolha o conjugado', 'Multiplicamos por $\sqrt{x+4}+3$ no numerador e no denominador.', 1), ('70000000-0000-4000-8000-000000100082', '40000000-0000-4000-8000-000000010008', 'Use produto notável', 'O numerador vira $(x+4)-9=x-5$.', 2), ('70000000-0000-4000-8000-000000100083', '40000000-0000-4000-8000-000000010008', 'Cancele o fator comum', 'Para $x\ne5$, resta $1/(\sqrt{x+4}+3)$.', 3), ('70000000-0000-4000-8000-000000100084', '40000000-0000-4000-8000-000000010008', 'Tome o limite', 'Em $x=5$, o denominador é $3+3=6$, dando $1/6$.', 4)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010009', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $\lim_{x\to0}\frac{\sin(4x)}{x}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100091', '40000000-0000-4000-8000-000000010009', 'A', '$4$', 1), ('50000000-0000-4000-8000-000000100092', '40000000-0000-4000-8000-000000010009', 'B', '$0$', 2), ('50000000-0000-4000-8000-000000100093', '40000000-0000-4000-8000-000000010009', 'C', '$1$', 3), ('50000000-0000-4000-8000-000000100094', '40000000-0000-4000-8000-000000010009', 'D', 'O limite não existe', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010009', '50000000-0000-4000-8000-000000100091') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010009', '30000000-0000-4000-8000-000000000018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100091', '40000000-0000-4000-8000-000000010009', 'Use o limite fundamental $\lim_{u\to0}\sin u/u=1$.', 1), ('60000000-0000-4000-8000-000000100092', '40000000-0000-4000-8000-000000010009', 'Faça aparecer $4x$ também no denominador.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010009', '$4$', 'O argumento do seno é $4x$, e não apenas $x$. Separar um fator $4$ permite aplicar exatamente o limite fundamental.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100091', '40000000-0000-4000-8000-000000010009', 'Reescreva a fração', '$\frac{\sin(4x)}x=4\cdot\frac{\sin(4x)}{4x}$.', 1), ('70000000-0000-4000-8000-000000100092', '40000000-0000-4000-8000-000000010009', 'Aplique o limite fundamental', 'Quando $x\to0$, também $4x\to0$, então a fração tende a $1$.', 2), ('70000000-0000-4000-8000-000000100093', '40000000-0000-4000-8000-000000010009', 'Multiplique o fator externo', 'O limite total é $4\cdot1=4$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010010', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Qual é $\lim_{x\to\infty}\frac{3x^2-x+1}{2x^2+5}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100101', '40000000-0000-4000-8000-000000010010', 'A', '$3/2$', 1), ('50000000-0000-4000-8000-000000100102', '40000000-0000-4000-8000-000000010010', 'B', '$0$', 2), ('50000000-0000-4000-8000-000000100103', '40000000-0000-4000-8000-000000010010', 'C', '$2/3$', 3), ('50000000-0000-4000-8000-000000100104', '40000000-0000-4000-8000-000000010010', 'D', '$3$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010010', '50000000-0000-4000-8000-000000100101') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010010', '30000000-0000-4000-8000-000000000020', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100101', '40000000-0000-4000-8000-000000010010', 'Compare os graus do numerador e do denominador.', 1), ('60000000-0000-4000-8000-000000100102', '40000000-0000-4000-8000-000000010010', 'Divida todos os termos por $x^2$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010010', '$3/2$', 'Em uma razão de polinômios de mesmo grau, os termos de maior grau controlam o comportamento no infinito. Os termos com potências menores desaparecem ao dividir por $x^2$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100101', '40000000-0000-4000-8000-000000010010', 'Identifique os graus', 'Numerador e denominador têm grau $2$.', 1), ('70000000-0000-4000-8000-000000100102', '40000000-0000-4000-8000-000000010010', 'Normalize a expressão', 'Dividindo por $x^2$, obtemos $(3-1/x+1/x^2)/(2+5/x^2)$.', 2), ('70000000-0000-4000-8000-000000100103', '40000000-0000-4000-8000-000000010010', 'Passe ao limite', 'Os termos com $1/x$ e $1/x^2$ tendem a zero; sobra $3/2$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010011', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Para qual valor de $a$ a função $f(x)=ax+1$ se $x<2$ e $f(x)=x^2$ se $x\ge2$ é contínua em $x=2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100111', '40000000-0000-4000-8000-000000010011', 'A', '$a=3$', 1), ('50000000-0000-4000-8000-000000100112', '40000000-0000-4000-8000-000000010011', 'B', '$a=2$', 2), ('50000000-0000-4000-8000-000000100113', '40000000-0000-4000-8000-000000010011', 'C', '$a=1$', 3), ('50000000-0000-4000-8000-000000100114', '40000000-0000-4000-8000-000000010011', 'D', '$a=4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010011', '50000000-0000-4000-8000-000000100111') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010011', '30000000-0000-4000-8000-000000000019', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100111', '40000000-0000-4000-8000-000000010011', 'Continuidade exige que limite à esquerda, limite à direita e valor da função coincidam.', 1), ('60000000-0000-4000-8000-000000100112', '40000000-0000-4000-8000-000000010011', 'Em $x=2$, o ramo da direita vale $2^2$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010011', '$a=3$', 'A função por partes só pode ser contínua na junção quando as duas fórmulas produzem o mesmo valor ali. O ramo que inclui igualdade define também o valor de $f(2)$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100111', '40000000-0000-4000-8000-000000010011', 'Avalie o lado direito', 'Como $2\ge2$, $f(2)=2^2=4$.', 1), ('70000000-0000-4000-8000-000000100112', '40000000-0000-4000-8000-000000010011', 'Calcule o limite à esquerda', 'Pelo primeiro ramo, quando $x\to2^-$, o valor tende a $2a+1$.', 2), ('70000000-0000-4000-8000-000000100113', '40000000-0000-4000-8000-000000010011', 'Iguale os valores', 'A continuidade pede $2a+1=4$; portanto $a=3$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010012', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'O limite $\lim_{x\to0}\frac{|x|}{x}$ é:')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100121', '40000000-0000-4000-8000-000000010012', 'A', 'Não existe', 1), ('50000000-0000-4000-8000-000000100122', '40000000-0000-4000-8000-000000010012', 'B', '$0$', 2), ('50000000-0000-4000-8000-000000100123', '40000000-0000-4000-8000-000000010012', 'C', '$1$', 3), ('50000000-0000-4000-8000-000000100124', '40000000-0000-4000-8000-000000010012', 'D', '$-1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010012', '50000000-0000-4000-8000-000000100121') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010012', '30000000-0000-4000-8000-000000000017', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100121', '40000000-0000-4000-8000-000000010012', 'Compare as aproximações pela esquerda e pela direita.', 1), ('60000000-0000-4000-8000-000000100122', '40000000-0000-4000-8000-000000010012', 'Para $x>0$, $|x|=x$; para $x<0$, $|x|=-x$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010012', 'Não existe.', 'Um limite bilateral existe apenas quando as tendências pelos dois lados são iguais. Aqui, o módulo altera a fórmula em cada lado de zero.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100121', '40000000-0000-4000-8000-000000010012', 'Aproxime pela direita', 'Se $x>0$, $|x|/x=x/x=1$.', 1), ('70000000-0000-4000-8000-000000100122', '40000000-0000-4000-8000-000000010012', 'Aproxime pela esquerda', 'Se $x<0$, $|x|/x=(-x)/x=-1$.', 2), ('70000000-0000-4000-8000-000000100123', '40000000-0000-4000-8000-000000010012', 'Compare os resultados', 'Como $1\ne-1$, os limites laterais diferem e o limite bilateral não existe.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010013', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $\lim_{x\to1}\frac{\ln x}{x-1}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100131', '40000000-0000-4000-8000-000000010013', 'A', '$1$', 1), ('50000000-0000-4000-8000-000000100132', '40000000-0000-4000-8000-000000010013', 'B', '$0$', 2), ('50000000-0000-4000-8000-000000100133', '40000000-0000-4000-8000-000000010013', 'C', '$e$', 3), ('50000000-0000-4000-8000-000000100134', '40000000-0000-4000-8000-000000010013', 'D', 'O limite não existe', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010013', '50000000-0000-4000-8000-000000100131') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010013', '30000000-0000-4000-8000-000000000018', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100131', '40000000-0000-4000-8000-000000010013', 'A expressão tem forma $0/0$.', 1), ('60000000-0000-4000-8000-000000100132', '40000000-0000-4000-8000-000000010013', 'A derivada de $\ln x$ é $1/x$; a Regra de l''Hôpital é aplicável aqui.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010013', '$1$', 'Perto de $x=1$, $\ln x$ cresce aproximadamente como $x-1$. A Regra de l''Hôpital formaliza essa comparação ao derivar numerador e denominador.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100131', '40000000-0000-4000-8000-000000010013', 'Identifique a indeterminação', '$\ln1=0$ e $1-1=0$, portanto temos $0/0$.', 1), ('70000000-0000-4000-8000-000000100132', '40000000-0000-4000-8000-000000010013', 'Derive numerador e denominador', 'A razão passa a ser $(1/x)/1$.', 2), ('70000000-0000-4000-8000-000000100133', '40000000-0000-4000-8000-000000010013', 'Avalie em $1$', '$1/x$ tende a $1$ quando $x$ tende a $1$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010014', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'A função $f(x)=\frac{2x+1}{x-4}$ possui qual assíntota vertical?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100141', '40000000-0000-4000-8000-000000010014', 'A', '$x=4$', 1), ('50000000-0000-4000-8000-000000100142', '40000000-0000-4000-8000-000000010014', 'B', '$y=2$', 2), ('50000000-0000-4000-8000-000000100143', '40000000-0000-4000-8000-000000010014', 'C', '$x=-4$', 3), ('50000000-0000-4000-8000-000000100144', '40000000-0000-4000-8000-000000010014', 'D', '$y=4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010014', '50000000-0000-4000-8000-000000100141') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010014', '30000000-0000-4000-8000-000000000020', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100141', '40000000-0000-4000-8000-000000010014', 'Assíntotas verticais podem ocorrer onde o denominador zera sem cancelamento.', 1), ('60000000-0000-4000-8000-000000100142', '40000000-0000-4000-8000-000000010014', 'Resolva $x-4=0$ e confira o numerador nesse ponto.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010014', '$x=4$', 'O denominador fica zero em $x=4$, enquanto o numerador vale $9$, não zero. Assim, os valores de $f(x)$ crescem em módulo sem limite perto dessa reta vertical.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100141', '40000000-0000-4000-8000-000000010014', 'Encontre o zero do denominador', '$x-4=0$ fornece $x=4$.', 1), ('70000000-0000-4000-8000-000000100142', '40000000-0000-4000-8000-000000010014', 'Cheque o numerador', 'Em $x=4$, $2x+1=9$, portanto não há cancelamento.', 2), ('70000000-0000-4000-8000-000000100143', '40000000-0000-4000-8000-000000010014', 'Conclua', 'A reta $x=4$ é a assíntota vertical.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010015', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Se $f(x)=x^2$, qual é $f''(3)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100151', '40000000-0000-4000-8000-000000010015', 'A', '$6$', 1), ('50000000-0000-4000-8000-000000100152', '40000000-0000-4000-8000-000000010015', 'B', '$9$', 2), ('50000000-0000-4000-8000-000000100153', '40000000-0000-4000-8000-000000010015', 'C', '$3$', 3), ('50000000-0000-4000-8000-000000100154', '40000000-0000-4000-8000-000000010015', 'D', '$12$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010015', '50000000-0000-4000-8000-000000100151') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010015', '30000000-0000-4000-8000-000000000022', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100151', '40000000-0000-4000-8000-000000010015', 'A derivada de $x^n$ é $nx^{n-1}$.', 1), ('60000000-0000-4000-8000-000000100152', '40000000-0000-4000-8000-000000010015', 'Derive antes de substituir $x=3$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010015', '$6$', 'A derivada mede a taxa de variação instantânea, isto é, a inclinação da reta tangente. Para a parábola $x^2$, essa taxa cresce linearmente com $x$, por isso o valor em $3$ é maior que o valor no ponto $1$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100151', '40000000-0000-4000-8000-000000010015', 'Derive a função', '$f''(x)=2x$.', 1), ('70000000-0000-4000-8000-000000100152', '40000000-0000-4000-8000-000000010015', 'Avalie no ponto', '$f''(3)=2\cdot3$.', 2), ('70000000-0000-4000-8000-000000100153', '40000000-0000-4000-8000-000000010015', 'Conclua', '$f''(3)=6$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010016', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Qual é a derivada de $f(x)=5x^4-3x+7$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100161', '40000000-0000-4000-8000-000000010016', 'A', '$20x^3-3$', 1), ('50000000-0000-4000-8000-000000100162', '40000000-0000-4000-8000-000000010016', 'B', '$20x^4-3$', 2), ('50000000-0000-4000-8000-000000100163', '40000000-0000-4000-8000-000000010016', 'C', '$5x^3-3$', 3), ('50000000-0000-4000-8000-000000100164', '40000000-0000-4000-8000-000000010016', 'D', '$20x^3+7$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010016', '50000000-0000-4000-8000-000000100161') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010016', '30000000-0000-4000-8000-000000000023', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100161', '40000000-0000-4000-8000-000000010016', 'Derive cada termo separadamente.', 1), ('60000000-0000-4000-8000-000000100162', '40000000-0000-4000-8000-000000010016', 'A derivada de uma constante é zero.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010016', '$20x^3-3$', 'A regra da potência reduz o expoente e multiplica pelo expoente antigo. O termo constante não altera quando $x$ varia.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100161', '40000000-0000-4000-8000-000000010016', 'Derive o primeiro termo', '$(5x^4)''=5\cdot4x^3=20x^3$.', 1), ('70000000-0000-4000-8000-000000100162', '40000000-0000-4000-8000-000000010016', 'Derive os demais', '$(-3x)''=-3$ e $7''=0$.', 2), ('70000000-0000-4000-8000-000000100163', '40000000-0000-4000-8000-000000010016', 'Some os resultados', '$f''(x)=20x^3-3$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010017', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule a derivada de $f(x)=x^2(x+1)$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100171', '40000000-0000-4000-8000-000000010017', 'A', '$3x^2+2x$', 1), ('50000000-0000-4000-8000-000000100172', '40000000-0000-4000-8000-000000010017', 'B', '$2x(x+1)$', 2), ('50000000-0000-4000-8000-000000100173', '40000000-0000-4000-8000-000000010017', 'C', '$3x^2+1$', 3), ('50000000-0000-4000-8000-000000100174', '40000000-0000-4000-8000-000000010017', 'D', '$x^3+x^2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010017', '50000000-0000-4000-8000-000000100171') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010017', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100171', '40000000-0000-4000-8000-000000010017', 'Você pode usar a regra do produto ou expandir antes.', 1), ('60000000-0000-4000-8000-000000100172', '40000000-0000-4000-8000-000000010017', 'Ao expandir, obtenha $x^3+x^2$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010017', '$3x^2+2x$', 'Em produtos de polinômios simples, expandir pode tornar a derivação transparente. A alternativa que repete apenas parte do produto esquece a contribuição de um fator.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100171', '40000000-0000-4000-8000-000000010017', 'Expanda o produto', '$x^2(x+1)=x^3+x^2$.', 1), ('70000000-0000-4000-8000-000000100172', '40000000-0000-4000-8000-000000010017', 'Derive termo a termo', '$(x^3+x^2)''=3x^2+2x$.', 2), ('70000000-0000-4000-8000-000000100173', '40000000-0000-4000-8000-000000010017', 'Escreva o resultado', '$f''(x)=3x^2+2x$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010018', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é a derivada de $f(x)=(3x-2)^5$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100181', '40000000-0000-4000-8000-000000010018', 'A', '$15(3x-2)^4$', 1), ('50000000-0000-4000-8000-000000100182', '40000000-0000-4000-8000-000000010018', 'B', '$5(3x-2)^4$', 2), ('50000000-0000-4000-8000-000000100183', '40000000-0000-4000-8000-000000010018', 'C', '$15(3x-2)^5$', 3), ('50000000-0000-4000-8000-000000100184', '40000000-0000-4000-8000-000000010018', 'D', '$(3x-2)^4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010018', '50000000-0000-4000-8000-000000100181') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010018', '30000000-0000-4000-8000-000000000025', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100181', '40000000-0000-4000-8000-000000010018', 'Há uma função externa elevada à quinta potência e uma função interna $3x-2$.', 1), ('60000000-0000-4000-8000-000000100182', '40000000-0000-4000-8000-000000010018', 'Multiplique pela derivada da parte interna.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010018', '$15(3x-2)^4$', 'A regra da cadeia combina a variação da potência externa com a variação da expressão interna. Esquecer o fator $3$ é o deslize mais comum.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100181', '40000000-0000-4000-8000-000000010018', 'Derive a camada externa', 'A derivada de $u^5$ é $5u^4$.', 1), ('70000000-0000-4000-8000-000000100182', '40000000-0000-4000-8000-000000010018', 'Substitua a expressão interna', 'Isso dá $5(3x-2)^4$.', 2), ('70000000-0000-4000-8000-000000100183', '40000000-0000-4000-8000-000000010018', 'Aplique a cadeia', 'Como $(3x-2)''=3$, o resultado é $15(3x-2)^4$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010019', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é a derivada de $f(x)=\frac{x+1}{x-2}$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100191', '40000000-0000-4000-8000-000000010019', 'A', '$-3/(x-2)^2$', 1), ('50000000-0000-4000-8000-000000100192', '40000000-0000-4000-8000-000000010019', 'B', '$1/(x-2)^2$', 2), ('50000000-0000-4000-8000-000000100193', '40000000-0000-4000-8000-000000010019', 'C', '$3/(x-2)^2$', 3), ('50000000-0000-4000-8000-000000100194', '40000000-0000-4000-8000-000000010019', 'D', '$-3/(x-2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010019', '50000000-0000-4000-8000-000000100191') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010019', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100191', '40000000-0000-4000-8000-000000010019', 'Use $(u/v)''=(u''v-uv'')/v^2$.', 1), ('60000000-0000-4000-8000-000000100192', '40000000-0000-4000-8000-000000010019', 'Aqui $u''=1$ e $v''=1$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010019', '$-3/(x-2)^2$', 'No quociente, a ordem da subtração importa. O numerador da derivada mede a diferença entre a contribuição do numerador e a do denominador.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100191', '40000000-0000-4000-8000-000000010019', 'Identifique as partes', '$u=x+1$, $v=x-2$ e $u''=v''=1$.', 1), ('70000000-0000-4000-8000-000000100192', '40000000-0000-4000-8000-000000010019', 'Aplique a regra', '$f''=((x-2)-(x+1))/(x-2)^2$.', 2), ('70000000-0000-4000-8000-000000100193', '40000000-0000-4000-8000-000000010019', 'Simplifique', 'O numerador é $-3$, resultando em $-3/(x-2)^2$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010020', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Determine $\frac{d}{dx}\sqrt{1+x^2}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100201', '40000000-0000-4000-8000-000000010020', 'A', '$x/\sqrt{1+x^2}$', 1), ('50000000-0000-4000-8000-000000100202', '40000000-0000-4000-8000-000000010020', 'B', '$1/(2\sqrt{1+x^2})$', 2), ('50000000-0000-4000-8000-000000100203', '40000000-0000-4000-8000-000000010020', 'C', '$2x/\sqrt{1+x^2}$', 3), ('50000000-0000-4000-8000-000000100204', '40000000-0000-4000-8000-000000010020', 'D', '$\sqrt{1+x^2}$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010020', '50000000-0000-4000-8000-000000100201') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010020', '30000000-0000-4000-8000-000000000025', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100201', '40000000-0000-4000-8000-000000010020', 'Reescreva a raiz como $(1+x^2)^{1/2}$.', 1), ('60000000-0000-4000-8000-000000100202', '40000000-0000-4000-8000-000000010020', 'A regra da cadeia introduz a derivada de $1+x^2$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010020', '$x/\sqrt{1+x^2}$', 'A raiz é uma potência de expoente $1/2$. A derivada externa cria o fator $1/2$, que se cancela com o $2$ da derivada interna.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100201', '40000000-0000-4000-8000-000000010020', 'Reescreva a raiz', '$\sqrt{1+x^2}=(1+x^2)^{1/2}$.', 1), ('70000000-0000-4000-8000-000000100202', '40000000-0000-4000-8000-000000010020', 'Derive pela cadeia', '$\frac12(1+x^2)^{-1/2}\cdot2x$.', 2), ('70000000-0000-4000-8000-000000100203', '40000000-0000-4000-8000-000000010020', 'Simplifique', 'Os fatores $1/2$ e $2$ se cancelam: $x/\sqrt{1+x^2}$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010021', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Se $x^2+y^2=25$, qual é $dy/dx$ em termos de $x$ e $y$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100211', '40000000-0000-4000-8000-000000010021', 'A', '$-x/y$', 1), ('50000000-0000-4000-8000-000000100212', '40000000-0000-4000-8000-000000010021', 'B', '$x/y$', 2), ('50000000-0000-4000-8000-000000100213', '40000000-0000-4000-8000-000000010021', 'C', '$-y/x$', 3), ('50000000-0000-4000-8000-000000100214', '40000000-0000-4000-8000-000000010021', 'D', '$2x+2y$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010021', '50000000-0000-4000-8000-000000100211') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010021', '30000000-0000-4000-8000-000000000026', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100211', '40000000-0000-4000-8000-000000010021', 'Derive os dois lados em relação a $x$.', 1), ('60000000-0000-4000-8000-000000100212', '40000000-0000-4000-8000-000000010021', 'Ao derivar $y^2$, lembre-se de $y''$ pela regra da cadeia.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010021', '$-x/y$', 'A equação define $y$ implicitamente como função de $x$. Por isso, a derivada de $y^2$ precisa carregar a taxa desconhecida $dy/dx$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100211', '40000000-0000-4000-8000-000000010021', 'Derive a igualdade', '$2x+2y,y''=0$.', 1), ('70000000-0000-4000-8000-000000100212', '40000000-0000-4000-8000-000000010021', 'Isole o termo com $y$', '$2y,y''=-2x$.', 2), ('70000000-0000-4000-8000-000000100213', '40000000-0000-4000-8000-000000010021', 'Divida por $2y$', '$y''=-x/y$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010022', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é a derivada de $f(x)=\ln(x^3)$ para $x>0$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100221', '40000000-0000-4000-8000-000000010022', 'A', '$3/x$', 1), ('50000000-0000-4000-8000-000000100222', '40000000-0000-4000-8000-000000010022', 'B', '$1/x^3$', 2), ('50000000-0000-4000-8000-000000100223', '40000000-0000-4000-8000-000000010022', 'C', '$3x^2$', 3), ('50000000-0000-4000-8000-000000100224', '40000000-0000-4000-8000-000000010022', 'D', '$\ln(3x^2)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010022', '50000000-0000-4000-8000-000000100221') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010022', '30000000-0000-4000-8000-000000000026', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100221', '40000000-0000-4000-8000-000000010022', 'Use $\frac d{dx}\ln u=u''/u$.', 1), ('60000000-0000-4000-8000-000000100222', '40000000-0000-4000-8000-000000010022', 'A derivada de $x^3$ é $3x^2$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010022', '$3/x$', 'A derivada do logaritmo natural divide a taxa de variação do argumento pelo próprio argumento. O resultado pode ser simplificado cancelando duas potências de $x$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100221', '40000000-0000-4000-8000-000000010022', 'Escolha o argumento', 'Tome $u=x^3$, então $u''=3x^2$.', 1), ('70000000-0000-4000-8000-000000100222', '40000000-0000-4000-8000-000000010022', 'Aplique a fórmula', '$f''=3x^2/x^3$.', 2), ('70000000-0000-4000-8000-000000100223', '40000000-0000-4000-8000-000000010022', 'Simplifique', '$3x^2/x^3=3/x$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010023', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Uma posição é dada por $s(t)=4t^2-2t$. Qual é a velocidade em $t=1$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100231', '40000000-0000-4000-8000-000000010023', 'A', '$6$', 1), ('50000000-0000-4000-8000-000000100232', '40000000-0000-4000-8000-000000010023', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000100233', '40000000-0000-4000-8000-000000010023', 'C', '$4$', 3), ('50000000-0000-4000-8000-000000100234', '40000000-0000-4000-8000-000000010023', 'D', '$8$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010023', '50000000-0000-4000-8000-000000100231') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010023', '30000000-0000-4000-8000-000000000023', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100231', '40000000-0000-4000-8000-000000010023', 'Velocidade é a derivada da posição.', 1), ('60000000-0000-4000-8000-000000100232', '40000000-0000-4000-8000-000000010023', 'Primeiro calcule $s''(t)$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010023', '$6$', 'A velocidade instantânea mostra a taxa de mudança da posição no tempo. Não se deve confundi-la com a posição $s(1)$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100231', '40000000-0000-4000-8000-000000010023', 'Derive a posição', '$s''(t)=8t-2$.', 1), ('70000000-0000-4000-8000-000000100232', '40000000-0000-4000-8000-000000010023', 'Use o instante indicado', '$s''(1)=8\cdot1-2$.', 2), ('70000000-0000-4000-8000-000000100233', '40000000-0000-4000-8000-000000010023', 'Conclua', 'A velocidade é $6$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010024', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Para $f(x)=x^2$, use a linearização em $a=4$ para aproximar $f(4,1)$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100241', '40000000-0000-4000-8000-000000010024', 'A', '$16,8$', 1), ('50000000-0000-4000-8000-000000100242', '40000000-0000-4000-8000-000000010024', 'B', '$16,1$', 2), ('50000000-0000-4000-8000-000000100243', '40000000-0000-4000-8000-000000010024', 'C', '$17,2$', 3), ('50000000-0000-4000-8000-000000100244', '40000000-0000-4000-8000-000000010024', 'D', '$8,2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010024', '50000000-0000-4000-8000-000000100241') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010024', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100241', '40000000-0000-4000-8000-000000010024', 'A linearização é $L(x)=f(a)+f''(a)(x-a)$.', 1), ('60000000-0000-4000-8000-000000100242', '40000000-0000-4000-8000-000000010024', 'Calcule $f(4)$ e $f''(4)$ antes.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010024', '$16,8$', 'A reta tangente em $x=4$ fornece uma aproximação local para a função. Como $4,1$ está perto de $4$, ela é apropriada para estimar o quadrado.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100241', '40000000-0000-4000-8000-000000010024', 'Calcule os dados no ponto', '$f(4)=16$ e $f''(x)=2x$, logo $f''(4)=8$.', 1), ('70000000-0000-4000-8000-000000100242', '40000000-0000-4000-8000-000000010024', 'Monte a reta tangente', '$L(x)=16+8(x-4)$.', 2), ('70000000-0000-4000-8000-000000100243', '40000000-0000-4000-8000-000000010024', 'Aproxime em $4,1$', '$L(4,1)=16+8(0,1)=16,8$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010025', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é a derivada de $f(x)=\sin(x^2)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100251', '40000000-0000-4000-8000-000000010025', 'A', '$2xcos(x^2)$', 1), ('50000000-0000-4000-8000-000000100252', '40000000-0000-4000-8000-000000010025', 'B', '$\cos(x^2)$', 2), ('50000000-0000-4000-8000-000000100253', '40000000-0000-4000-8000-000000010025', 'C', '$2xsin(x)$', 3), ('50000000-0000-4000-8000-000000100254', '40000000-0000-4000-8000-000000010025', 'D', '$\cos(x)$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010025', '50000000-0000-4000-8000-000000100251') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010025', '30000000-0000-4000-8000-000000000025', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100251', '40000000-0000-4000-8000-000000010025', 'A derivada externa de seno é cosseno.', 1), ('60000000-0000-4000-8000-000000100252', '40000000-0000-4000-8000-000000010025', 'O argumento $x^2$ também varia com $x$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010025', '$2xcos(x^2)$', 'O cosseno mantém o mesmo argumento interno. O fator $2x$ vem da taxa de variação desse argumento: $x^2$ não cresce uma unidade para cada unidade de $x$, então a derivada não pode ser apenas $\cos(x^2)$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100251', '40000000-0000-4000-8000-000000010025', 'Identifique a composição', 'A função externa é $\sin u$ com $u=x^2$.', 1), ('70000000-0000-4000-8000-000000100252', '40000000-0000-4000-8000-000000010025', 'Derive a parte externa', 'A derivada é $\cos(u)$.', 2), ('70000000-0000-4000-8000-000000100253', '40000000-0000-4000-8000-000000010025', 'Multiplique pela interna', 'Como $u''=2x$, fica $2xcos(x^2)$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010026', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é a derivada de $f(x)=xe^x$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100261', '40000000-0000-4000-8000-000000010026', 'A', '$e^x(x+1)$', 1), ('50000000-0000-4000-8000-000000100262', '40000000-0000-4000-8000-000000010026', 'B', '$xe^x$', 2), ('50000000-0000-4000-8000-000000100263', '40000000-0000-4000-8000-000000010026', 'C', '$e^x$', 3), ('50000000-0000-4000-8000-000000100264', '40000000-0000-4000-8000-000000010026', 'D', '$x^2e^x$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010026', '50000000-0000-4000-8000-000000100261') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010026', '30000000-0000-4000-8000-000000000024', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100261', '40000000-0000-4000-8000-000000010026', 'É um produto de duas funções que dependem de $x$.', 1), ('60000000-0000-4000-8000-000000100262', '40000000-0000-4000-8000-000000010026', 'Use $u''v+uv''$ e lembre-se de que $(e^x)''=e^x$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010026', '$e^x(x+1)$', 'Cada fator do produto pode variar. A regra do produto soma as duas maneiras pelas quais o valor total muda: variar $x$ mantendo momentaneamente $e^x$, e variar $e^x$ mantendo momentaneamente $x$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100261', '40000000-0000-4000-8000-000000010026', 'Aplique a regra do produto', '$(xe^x)''=1\cdot e^x+xcdot e^x$.', 1), ('70000000-0000-4000-8000-000000100262', '40000000-0000-4000-8000-000000010026', 'Fatore o termo comum', '$e^x+xe^x=e^x(1+x)$.', 2), ('70000000-0000-4000-8000-000000100263', '40000000-0000-4000-8000-000000010026', 'Organize', '$f''(x)=e^x(x+1)$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010027', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Se $f(x)=\frac{1}{x}$, qual é $f''(x)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100271', '40000000-0000-4000-8000-000000010027', 'A', '$-1/x^2$', 1), ('50000000-0000-4000-8000-000000100272', '40000000-0000-4000-8000-000000010027', 'B', '$1/x^2$', 2), ('50000000-0000-4000-8000-000000100273', '40000000-0000-4000-8000-000000010027', 'C', '$-1/x$', 3), ('50000000-0000-4000-8000-000000100274', '40000000-0000-4000-8000-000000010027', 'D', '$x$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010027', '50000000-0000-4000-8000-000000100271') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010027', '30000000-0000-4000-8000-000000000023', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100271', '40000000-0000-4000-8000-000000010027', 'Escreva $1/x$ como $x^{-1}$.', 1), ('60000000-0000-4000-8000-000000100272', '40000000-0000-4000-8000-000000010027', 'A regra da potência também vale para expoentes negativos.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010027', '$-1/x^2$', 'A forma de potência revela que o expoente diminui de $-1$ para $-2$. O sinal negativo vem do próprio expoente.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100271', '40000000-0000-4000-8000-000000010027', 'Reescreva a função', '$1/x=x^{-1}$.', 1), ('70000000-0000-4000-8000-000000100272', '40000000-0000-4000-8000-000000010027', 'Aplique a regra da potência', '$(x^{-1})''=-1x^{-2}$.', 2), ('70000000-0000-4000-8000-000000100273', '40000000-0000-4000-8000-000000010027', 'Use fração novamente', '$-x^{-2}=-1/x^2$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010028', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é a equação da reta tangente a $f(x)=x^2$ no ponto de abscissa $x=2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100281', '40000000-0000-4000-8000-000000010028', 'A', '$y=4x-4$', 1), ('50000000-0000-4000-8000-000000100282', '40000000-0000-4000-8000-000000010028', 'B', '$y=2x$', 2), ('50000000-0000-4000-8000-000000100283', '40000000-0000-4000-8000-000000010028', 'C', '$y=4x$', 3), ('50000000-0000-4000-8000-000000100284', '40000000-0000-4000-8000-000000010028', 'D', '$y=2x-2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010028', '50000000-0000-4000-8000-000000100281') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010028', '30000000-0000-4000-8000-000000000022', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100281', '40000000-0000-4000-8000-000000010028', 'A inclinação é $f''(2)$.', 1), ('60000000-0000-4000-8000-000000100282', '40000000-0000-4000-8000-000000010028', 'A reta passa pelo ponto $(2,f(2))$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010028', '$y=4x-4$', 'Uma reta tangente é determinada pelo ponto de contato e pela inclinação instantânea. É preciso usar ambos; apenas a derivada não define sua posição.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100281', '40000000-0000-4000-8000-000000010028', 'Encontre o ponto', '$f(2)=4$, logo o ponto é $(2,4)$.', 1), ('70000000-0000-4000-8000-000000100282', '40000000-0000-4000-8000-000000010028', 'Encontre a inclinação', '$f''(x)=2x$, então $f''(2)=4$.', 2), ('70000000-0000-4000-8000-000000100283', '40000000-0000-4000-8000-000000010028', 'Use ponto-inclinação', '$y-4=4(x-2)$, isto é, $y=4x-4$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010029', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Em qual ponto crítico de $f(x)=x^2-4x$ a derivada se anula?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100291', '40000000-0000-4000-8000-000000010029', 'A', '$x=2$', 1), ('50000000-0000-4000-8000-000000100292', '40000000-0000-4000-8000-000000010029', 'B', '$x=-2$', 2), ('50000000-0000-4000-8000-000000100293', '40000000-0000-4000-8000-000000010029', 'C', '$x=4$', 3), ('50000000-0000-4000-8000-000000100294', '40000000-0000-4000-8000-000000010029', 'D', '$x=0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010029', '50000000-0000-4000-8000-000000100291') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010029', '30000000-0000-4000-8000-000000000029', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100291', '40000000-0000-4000-8000-000000010029', 'Pontos críticos candidatos ocorrem onde $f''(x)=0$ ou não existe.', 1), ('60000000-0000-4000-8000-000000100292', '40000000-0000-4000-8000-000000010029', 'Derive o polinômio.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010029', '$x=2$', 'Para uma função polinomial, a derivada existe em todo lugar. Assim, basta resolver a equação que faz a inclinação ser zero.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100291', '40000000-0000-4000-8000-000000010029', 'Derive a função', '$f''(x)=2x-4$.', 1), ('70000000-0000-4000-8000-000000100292', '40000000-0000-4000-8000-000000010029', 'Anule a derivada', '$2x-4=0$.', 2), ('70000000-0000-4000-8000-000000100293', '40000000-0000-4000-8000-000000010029', 'Resolva', '$2x=4$, portanto $x=2$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010030', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é o valor máximo de $f(x)=-x^2+6x$ nos reais?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100301', '40000000-0000-4000-8000-000000010030', 'A', '$9$', 1), ('50000000-0000-4000-8000-000000100302', '40000000-0000-4000-8000-000000010030', 'B', '$6$', 2), ('50000000-0000-4000-8000-000000100303', '40000000-0000-4000-8000-000000010030', 'C', '$-9$', 3), ('50000000-0000-4000-8000-000000100304', '40000000-0000-4000-8000-000000010030', 'D', '$0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010030', '50000000-0000-4000-8000-000000100301') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010030', '30000000-0000-4000-8000-000000000029', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100301', '40000000-0000-4000-8000-000000010030', 'Encontre o ponto onde a derivada é zero.', 1), ('60000000-0000-4000-8000-000000100302', '40000000-0000-4000-8000-000000010030', 'A parábola abre para baixo, então o ponto crítico é máximo.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010030', '$9$', 'A derivada localiza o vértice da parábola. Como o coeficiente de $x^2$ é negativo, o vértice fornece o maior valor da função.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100301', '40000000-0000-4000-8000-000000010030', 'Derive', '$f''(x)=-2x+6$.', 1), ('70000000-0000-4000-8000-000000100302', '40000000-0000-4000-8000-000000010030', 'Encontre o crítico', '$-2x+6=0$ dá $x=3$.', 2), ('70000000-0000-4000-8000-000000100303', '40000000-0000-4000-8000-000000010030', 'Avalie a função', '$f(3)=-(3)^2+6\cdot3=-9+18=9$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010031', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Se $f''(x)>0$ em um intervalo, como $f$ se comporta nesse intervalo?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100311', '40000000-0000-4000-8000-000000010031', 'A', 'É crescente', 1), ('50000000-0000-4000-8000-000000100312', '40000000-0000-4000-8000-000000010031', 'B', 'É decrescente', 2), ('50000000-0000-4000-8000-000000100313', '40000000-0000-4000-8000-000000010031', 'C', 'É constante', 3), ('50000000-0000-4000-8000-000000100314', '40000000-0000-4000-8000-000000010031', 'D', 'Tem necessariamente um máximo', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010031', '50000000-0000-4000-8000-000000100311') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010031', '30000000-0000-4000-8000-000000000030', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100311', '40000000-0000-4000-8000-000000010031', 'A derivada indica a inclinação local do gráfico.', 1), ('60000000-0000-4000-8000-000000100312', '40000000-0000-4000-8000-000000010031', 'Inclinações positivas apontam para cima da esquerda para a direita.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010031', 'É crescente.', 'Derivada positiva significa que pequenos aumentos em $x$ produzem aumentos em $f(x)$. Isso caracteriza crescimento no intervalo, sem garantir por si só um máximo.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100311', '40000000-0000-4000-8000-000000010031', 'Interprete o sinal', '$f''(x)>0$ significa inclinação positiva.', 1), ('70000000-0000-4000-8000-000000100312', '40000000-0000-4000-8000-000000010031', 'Compare valores próximos', 'Ao aumentar $x$, a função aumenta localmente.', 2), ('70000000-0000-4000-8000-000000100313', '40000000-0000-4000-8000-000000010031', 'Conclua no intervalo', 'Se isso vale em todo o intervalo, $f$ é crescente nele.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010032', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $lim_{x	o0}\frac{e^x-1}{x}$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100321', '40000000-0000-4000-8000-000000010032', 'A', '$1$', 1), ('50000000-0000-4000-8000-000000100322', '40000000-0000-4000-8000-000000010032', 'B', '$0$', 2), ('50000000-0000-4000-8000-000000100323', '40000000-0000-4000-8000-000000010032', 'C', '$e$', 3), ('50000000-0000-4000-8000-000000100324', '40000000-0000-4000-8000-000000010032', 'D', 'Não existe', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010032', '50000000-0000-4000-8000-000000100321') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010032', '30000000-0000-4000-8000-000000000031', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100321', '40000000-0000-4000-8000-000000010032', 'A substituição dá $0/0$.', 1), ('60000000-0000-4000-8000-000000100322', '40000000-0000-4000-8000-000000010032', 'Pela Regra de l''Hôpital, derive numerador e denominador.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010032', '$1$', 'A diferença $e^x-1$ é aproximadamente igual a $x$ perto de zero. A Regra de l''Hôpital confirma essa taxa comparando suas derivadas.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100321', '40000000-0000-4000-8000-000000010032', 'Verifique a forma', '$e^0-1=0$ e o denominador também é $0$.', 1), ('70000000-0000-4000-8000-000000100322', '40000000-0000-4000-8000-000000010032', 'Derive os dois termos', 'A razão vira $e^x/1$.', 2), ('70000000-0000-4000-8000-000000100323', '40000000-0000-4000-8000-000000010032', 'Avalie no limite', '$e^x$ tende a $e^0=1$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010033', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Um retângulo tem perímetro $20$ e lados $x$ e $10-x$. Para qual $x$ sua área é máxima?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100331', '40000000-0000-4000-8000-000000010033', 'A', '$5$', 1), ('50000000-0000-4000-8000-000000100332', '40000000-0000-4000-8000-000000010033', 'B', '$10$', 2), ('50000000-0000-4000-8000-000000100333', '40000000-0000-4000-8000-000000010033', 'C', '$4$', 3), ('50000000-0000-4000-8000-000000100334', '40000000-0000-4000-8000-000000010033', 'D', '$2,5$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010033', '50000000-0000-4000-8000-000000100331') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010033', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100331', '40000000-0000-4000-8000-000000010033', 'Escreva a área usando apenas $x$.', 1), ('60000000-0000-4000-8000-000000100332', '40000000-0000-4000-8000-000000010033', 'Maximize a parábola $A(x)=x(10-x)$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010033', '$5$', 'Com perímetro fixo, a área do retângulo é uma parábola voltada para baixo. O máximo ocorre no vértice, quando os lados são iguais.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100331', '40000000-0000-4000-8000-000000010033', 'Monte a área', '$A(x)=x(10-x)=10x-x^2$.', 1), ('70000000-0000-4000-8000-000000100332', '40000000-0000-4000-8000-000000010033', 'Derive', '$A''(x)=10-2x$.', 2), ('70000000-0000-4000-8000-000000100333', '40000000-0000-4000-8000-000000010033', 'Anule e interprete', '$10-2x=0$ dá $x=5$; como a parábola abre para baixo, é máximo.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010034', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'O raio de um círculo cresce a $2$ cm/s. Quando $r=3$ cm, qual é $dA/dt$ para $A=\pi r^2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100341', '40000000-0000-4000-8000-000000010034', 'A', '$12\pi$ cm²/s', 1), ('50000000-0000-4000-8000-000000100342', '40000000-0000-4000-8000-000000010034', 'B', '$6\pi$ cm²/s', 2), ('50000000-0000-4000-8000-000000100343', '40000000-0000-4000-8000-000000010034', 'C', '$18\pi$ cm²/s', 3), ('50000000-0000-4000-8000-000000100344', '40000000-0000-4000-8000-000000010034', 'D', '$4\pi$ cm²/s', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010034', '50000000-0000-4000-8000-000000100341') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010034', '30000000-0000-4000-8000-000000000027', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100341', '40000000-0000-4000-8000-000000010034', 'Diferencie a fórmula da área em relação ao tempo.', 1), ('60000000-0000-4000-8000-000000100342', '40000000-0000-4000-8000-000000010034', 'Use $dA/dt=2\pi r,dr/dt$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010034', '$12\pi$ cm²/s', 'A área muda porque o raio muda. A regra da cadeia relaciona diretamente a taxa do raio à taxa da área; o valor de $r$ é indispensável, pois um mesmo aumento de raio cria uma área adicional maior em círculos maiores.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100341', '40000000-0000-4000-8000-000000010034', 'Escreva a relação', '$A=\pi r^2$.', 1), ('70000000-0000-4000-8000-000000100342', '40000000-0000-4000-8000-000000010034', 'Derive no tempo', '$dA/dt=2\pi r,dr/dt$.', 2), ('70000000-0000-4000-8000-000000100343', '40000000-0000-4000-8000-000000010034', 'Substitua os dados', '$2picdot3\cdot2=12\pi$ cm²/s.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010035', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Para aproximar uma raiz de $f(x)=x^2-2$ pelo método de Newton, partindo de $x_0=1$, qual é $x_1$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100351', '40000000-0000-4000-8000-000000010035', 'A', '$3/2$', 1), ('50000000-0000-4000-8000-000000100352', '40000000-0000-4000-8000-000000010035', 'B', '$2$', 2), ('50000000-0000-4000-8000-000000100353', '40000000-0000-4000-8000-000000010035', 'C', '$1/2$', 3), ('50000000-0000-4000-8000-000000100354', '40000000-0000-4000-8000-000000010035', 'D', '$\sqrt2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010035', '50000000-0000-4000-8000-000000100351') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010035', '30000000-0000-4000-8000-000000000033', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100351', '40000000-0000-4000-8000-000000010035', 'Use $x_{n+1}=x_n-f(x_n)/f''(x_n)$.', 1), ('60000000-0000-4000-8000-000000100352', '40000000-0000-4000-8000-000000010035', 'Calcule $f(1)$ e $f''(1)$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010035', '$3/2$', 'O método de Newton usa a interseção com o eixo da reta tangente como próximo palpite. Uma iteração ainda não entrega a raiz exata, mas aproxima $\sqrt2$.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100351', '40000000-0000-4000-8000-000000010035', 'Calcule função e derivada', '$f(1)=-1$ e $f''(x)=2x$, logo $f''(1)=2$.', 1), ('70000000-0000-4000-8000-000000100352', '40000000-0000-4000-8000-000000010035', 'Aplique a fórmula', '$x_1=1-(-1)/2$.', 2), ('70000000-0000-4000-8000-000000100353', '40000000-0000-4000-8000-000000010035', 'Simplifique', '$x_1=1+1/2=3/2$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010036', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'A temperatura $T(t)=t^3-6t^2+9t$ tem ponto crítico não nulo em qual instante?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100361', '40000000-0000-4000-8000-000000010036', 'A', '$t=3$', 1), ('50000000-0000-4000-8000-000000100362', '40000000-0000-4000-8000-000000010036', 'B', '$t=6$', 2), ('50000000-0000-4000-8000-000000100363', '40000000-0000-4000-8000-000000010036', 'C', '$t=9$', 3), ('50000000-0000-4000-8000-000000100364', '40000000-0000-4000-8000-000000010036', 'D', '$t=1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010036', '50000000-0000-4000-8000-000000100361') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010036', '30000000-0000-4000-8000-000000000029', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100361', '40000000-0000-4000-8000-000000010036', 'Encontre $T''(t)$ e fatore.', 1), ('60000000-0000-4000-8000-000000100362', '40000000-0000-4000-8000-000000010036', 'Além de $t=0$, procure o outro zero da derivada.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010036', '$t=3$', 'Os instantes críticos são aqueles em que a taxa de variação da temperatura se anula. Fatorar a derivada revela os dois candidatos.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100361', '40000000-0000-4000-8000-000000010036', 'Derive', '$T''(t)=3t^2-12t+9$.', 1), ('70000000-0000-4000-8000-000000100362', '40000000-0000-4000-8000-000000010036', 'Fatore', '$T''(t)=3(t^2-4t+3)=3(t-1)(t-3)$.', 2), ('70000000-0000-4000-8000-000000100363', '40000000-0000-4000-8000-000000010036', 'Escolha o crítico pedido', 'Os críticos são $1$ e $3$; o não nulo destacado é $3$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010037', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Se $f''(x)<0$ para $x<2$ e $f''(x)>0$ para $x>2$, o que ocorre em $x=2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100371', '40000000-0000-4000-8000-000000010037', 'A', 'Um mínimo local', 1), ('50000000-0000-4000-8000-000000100372', '40000000-0000-4000-8000-000000010037', 'B', 'Um máximo local', 2), ('50000000-0000-4000-8000-000000100373', '40000000-0000-4000-8000-000000010037', 'C', 'Nenhum extremo pode ser concluído', 3), ('50000000-0000-4000-8000-000000100374', '40000000-0000-4000-8000-000000010037', 'D', 'Uma assíntota vertical', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010037', '50000000-0000-4000-8000-000000100371') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010037', '30000000-0000-4000-8000-000000000030', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100371', '40000000-0000-4000-8000-000000010037', 'Observe a mudança do sinal da derivada.', 1), ('60000000-0000-4000-8000-000000100372', '40000000-0000-4000-8000-000000010037', 'A função passa de decrescente a crescente.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010037', 'Um mínimo local.', 'Antes de $2$, a função desce; depois de $2$, ela sobe. Essa troca de negativo para positivo caracteriza um vale local.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100371', '40000000-0000-4000-8000-000000010037', 'Leia o lado esquerdo', '$f''<0$ indica função decrescente antes de $2$.', 1), ('70000000-0000-4000-8000-000000100372', '40000000-0000-4000-8000-000000010037', 'Leia o lado direito', '$f''>0$ indica função crescente depois de $2$.', 2), ('70000000-0000-4000-8000-000000100373', '40000000-0000-4000-8000-000000010037', 'Conclua pelo teste da primeira derivada', 'A mudança de $-$ para $+$ produz mínimo local.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010038', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'A soma de dois números positivos é $12$. Quais valores maximizam o produto entre eles?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100381', '40000000-0000-4000-8000-000000010038', 'A', '$6$ e $6$', 1), ('50000000-0000-4000-8000-000000100382', '40000000-0000-4000-8000-000000010038', 'B', '$12$ e $0$', 2), ('50000000-0000-4000-8000-000000100383', '40000000-0000-4000-8000-000000010038', 'C', '$8$ e $4$', 3), ('50000000-0000-4000-8000-000000100384', '40000000-0000-4000-8000-000000010038', 'D', '$10$ e $2$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010038', '50000000-0000-4000-8000-000000100381') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010038', '30000000-0000-4000-8000-000000000032', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100381', '40000000-0000-4000-8000-000000010038', 'Se um número é $x$, o outro é $12-x$.', 1), ('60000000-0000-4000-8000-000000100382', '40000000-0000-4000-8000-000000010038', 'Maximize $P(x)=x(12-x)$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010038', '$6$ e $6$', 'O produto sob soma fixa é máximo quando os dois números se equilibram. O cálculo confirma a simetria por meio do vértice de uma parábola.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100381', '40000000-0000-4000-8000-000000010038', 'Modele o produto', '$P(x)=x(12-x)=12x-x^2$.', 1), ('70000000-0000-4000-8000-000000100382', '40000000-0000-4000-8000-000000010038', 'Encontre o crítico', '$P''(x)=12-2x=0$ dá $x=6$.', 2), ('70000000-0000-4000-8000-000000100383', '40000000-0000-4000-8000-000000010038', 'Recupere o outro número', '$12-6=6$, portanto os dois são $6$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010039', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Uma primitiva de $f(x)=6x^2$ é:')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100391', '40000000-0000-4000-8000-000000010039', 'A', '$2x^3+C$', 1), ('50000000-0000-4000-8000-000000100392', '40000000-0000-4000-8000-000000010039', 'B', '$6x^3+C$', 2), ('50000000-0000-4000-8000-000000100393', '40000000-0000-4000-8000-000000010039', 'C', '$3x^2+C$', 3), ('50000000-0000-4000-8000-000000100394', '40000000-0000-4000-8000-000000010039', 'D', '$2x^2+C$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010039', '50000000-0000-4000-8000-000000100391') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010039', '30000000-0000-4000-8000-000000000034', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100391', '40000000-0000-4000-8000-000000010039', 'Procure uma função cuja derivada seja $6x^2$.', 1), ('60000000-0000-4000-8000-000000100392', '40000000-0000-4000-8000-000000010039', 'A integral de $x^n$ é $x^{n+1}/(n+1)$, com $n
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010039', '$2x^3+C$', 'Integrar desfaz a derivação. A constante $C$ é necessária porque todas as constantes têm derivada zero; portanto, não há uma única primitiva, mas uma família inteira de funções com a mesma derivada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100391', '40000000-0000-4000-8000-000000010039', 'Aumente o expoente', 'A antiderivada de $x^2$ terá termo em $x^3$.', 1), ('70000000-0000-4000-8000-000000100392', '40000000-0000-4000-8000-000000010039', 'Ajuste o coeficiente', 'Para derivar em $6x^2$, usamos $2x^3$, pois $(2x^3)''=6x^2$.', 2), ('70000000-0000-4000-8000-000000100393', '40000000-0000-4000-8000-000000010039', 'Acrescente a constante', 'A família completa é $2x^3+C$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010040', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Calcule $\int_0^2 3x,dx$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100401', '40000000-0000-4000-8000-000000010040', 'A', '$6$', 1), ('50000000-0000-4000-8000-000000100402', '40000000-0000-4000-8000-000000010040', 'B', '$12$', 2), ('50000000-0000-4000-8000-000000100403', '40000000-0000-4000-8000-000000010040', 'C', '$3$', 3), ('50000000-0000-4000-8000-000000100404', '40000000-0000-4000-8000-000000010040', 'D', '$4$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010040', '50000000-0000-4000-8000-000000100401') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010040', '30000000-0000-4000-8000-000000000036', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100401', '40000000-0000-4000-8000-000000010040', 'Encontre uma primitiva de $3x$.', 1), ('60000000-0000-4000-8000-000000100402', '40000000-0000-4000-8000-000000010040', 'Depois avalie o limite superior menos o inferior.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010040', '$6$', 'A integral definida acumula a variação entre os limites. O Teorema Fundamental do Cálculo permite calculá-la usando uma primitiva.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100401', '40000000-0000-4000-8000-000000010040', 'Encontre a primitiva', '$\int3x,dx=\frac32x^2$.', 1), ('70000000-0000-4000-8000-000000100402', '40000000-0000-4000-8000-000000010040', 'Avalie em $2$', '$\frac32(2)^2=6$.', 2), ('70000000-0000-4000-8000-000000100403', '40000000-0000-4000-8000-000000010040', 'Avalie em $0$ e subtraia', '$\frac32(0)^2=0$, então o valor é $6-0=6$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010041', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Se $F(x)=\int_1^x (t^2+1),dt$, qual é $F''(x)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100411', '40000000-0000-4000-8000-000000010041', 'A', '$x^2+1$', 1), ('50000000-0000-4000-8000-000000100412', '40000000-0000-4000-8000-000000010041', 'B', '$2x$', 2), ('50000000-0000-4000-8000-000000100413', '40000000-0000-4000-8000-000000010041', 'C', '$x^3/3+x$', 3), ('50000000-0000-4000-8000-000000100414', '40000000-0000-4000-8000-000000010041', 'D', '$1$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010041', '50000000-0000-4000-8000-000000100411') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010041', '30000000-0000-4000-8000-000000000037', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100411', '40000000-0000-4000-8000-000000010041', 'Use a primeira parte do Teorema Fundamental do Cálculo.', 1), ('60000000-0000-4000-8000-000000100412', '40000000-0000-4000-8000-000000010041', 'A derivada de uma integral com limite superior $x$ recupera o integrando em $x$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010041', '$x^2+1$', 'A integral acumulada define uma nova função. Derivá-la recupera a taxa que estava sendo acumulada, sem necessidade de calcular a integral primeiro.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100411', '40000000-0000-4000-8000-000000010041', 'Observe a forma', 'O limite superior é a variável $x$.', 1), ('70000000-0000-4000-8000-000000100412', '40000000-0000-4000-8000-000000010041', 'Aplique o teorema', '$\frac d{dx}\int_1^x f(t),dt=f(x)$.', 2), ('70000000-0000-4000-8000-000000100413', '40000000-0000-4000-8000-000000010041', 'Substitua o integrando', '$F''(x)=x^2+1$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010042', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $\int 2xcos(x^2),dx$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100421', '40000000-0000-4000-8000-000000010042', 'A', '$\sin(x^2)+C$', 1), ('50000000-0000-4000-8000-000000100422', '40000000-0000-4000-8000-000000010042', 'B', '$2\sin(x^2)+C$', 2), ('50000000-0000-4000-8000-000000100423', '40000000-0000-4000-8000-000000010042', 'C', '$x^2\sin x+C$', 3), ('50000000-0000-4000-8000-000000100424', '40000000-0000-4000-8000-000000010042', 'D', '$-\sin(x^2)+C$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010042', '50000000-0000-4000-8000-000000100421') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010042', '30000000-0000-4000-8000-000000000038', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100421', '40000000-0000-4000-8000-000000010042', 'A expressão $x^2$ está dentro do cosseno.', 1), ('60000000-0000-4000-8000-000000100422', '40000000-0000-4000-8000-000000010042', 'Use $u=x^2$ e $du=2x,dx$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010042', '$\sin(x^2)+C$', 'A substituição reconhece uma função interna acompanhada exatamente por sua derivada. Isso transforma a integral em uma forma básica de cosseno.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100421', '40000000-0000-4000-8000-000000010042', 'Escolha a substituição', 'Tome $u=x^2$, então $du=2x,dx$.', 1), ('70000000-0000-4000-8000-000000100422', '40000000-0000-4000-8000-000000010042', 'Troque as partes', 'A integral vira $intcos u,du$.', 2), ('70000000-0000-4000-8000-000000100423', '40000000-0000-4000-8000-000000010042', 'Integre e retorne', '$intcos u,du=\sin u+C=\sin(x^2)+C$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010043', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'easy', 'published', 'Calcule $\int (4x^3-2),dx$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100431', '40000000-0000-4000-8000-000000010043', 'A', '$x^4-2x+C$', 1), ('50000000-0000-4000-8000-000000100432', '40000000-0000-4000-8000-000000010043', 'B', '$4x^4-2+C$', 2), ('50000000-0000-4000-8000-000000100433', '40000000-0000-4000-8000-000000010043', 'C', '$x^4-2+C$', 3), ('50000000-0000-4000-8000-000000100434', '40000000-0000-4000-8000-000000010043', 'D', '$x^4-2x$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010043', '50000000-0000-4000-8000-000000100431') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010043', '30000000-0000-4000-8000-000000000034', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100431', '40000000-0000-4000-8000-000000010043', 'Integre cada termo separadamente.', 1), ('60000000-0000-4000-8000-000000100432', '40000000-0000-4000-8000-000000010043', 'A integral de uma constante $-2$ é $-2x$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010043', '$x^4-2x+C$', 'A integral é linear: podemos tratar o termo polinomial e a constante independentemente. A constante de integração representa todas as primitivas possíveis.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100431', '40000000-0000-4000-8000-000000010043', 'Integre o primeiro termo', '$\int4x^3,dx=x^4$.', 1), ('70000000-0000-4000-8000-000000100432', '40000000-0000-4000-8000-000000010043', 'Integre a constante', '$\int-2,dx=-2x$.', 2), ('70000000-0000-4000-8000-000000100433', '40000000-0000-4000-8000-000000010043', 'Junte e acrescente $C$', '$x^4-2x+C$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010044', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $\int_1^3 (2x+1),dx$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100441', '40000000-0000-4000-8000-000000010044', 'A', '$10$', 1), ('50000000-0000-4000-8000-000000100442', '40000000-0000-4000-8000-000000010044', 'B', '$8$', 2), ('50000000-0000-4000-8000-000000100443', '40000000-0000-4000-8000-000000010044', 'C', '$12$', 3), ('50000000-0000-4000-8000-000000100444', '40000000-0000-4000-8000-000000010044', 'D', '$6$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010044', '50000000-0000-4000-8000-000000100441') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010044', '30000000-0000-4000-8000-000000000036', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100441', '40000000-0000-4000-8000-000000010044', 'Uma primitiva de $2x+1$ é $x^2+x$.', 1), ('60000000-0000-4000-8000-000000100442', '40000000-0000-4000-8000-000000010044', 'Avalie em $3$ e em $1$, nesta ordem.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010044', '$10$', 'A integral definida é a diferença entre os valores da primitiva nos extremos. Esquecer de subtrair o valor em $1$ cria um resultado excessivo.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100441', '40000000-0000-4000-8000-000000010044', 'Encontre a primitiva', '$\int(2x+1),dx=x^2+x$.', 1), ('70000000-0000-4000-8000-000000100442', '40000000-0000-4000-8000-000000010044', 'Avalie no limite superior', '$3^2+3=12$.', 2), ('70000000-0000-4000-8000-000000100443', '40000000-0000-4000-8000-000000010044', 'Subtraia o limite inferior', '$1^2+1=2$, então $12-2=10$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010045', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Se $G(x)=\int_{x}^{4} t^2,dt$, qual é $G''(x)$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100451', '40000000-0000-4000-8000-000000010045', 'A', '$-x^2$', 1), ('50000000-0000-4000-8000-000000100452', '40000000-0000-4000-8000-000000010045', 'B', '$x^2$', 2), ('50000000-0000-4000-8000-000000100453', '40000000-0000-4000-8000-000000010045', 'C', '$16-x^2$', 3), ('50000000-0000-4000-8000-000000100454', '40000000-0000-4000-8000-000000010045', 'D', '$2x$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010045', '50000000-0000-4000-8000-000000100451') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010045', '30000000-0000-4000-8000-000000000037', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100451', '40000000-0000-4000-8000-000000010045', 'O limite variável está embaixo, não em cima.', 1), ('60000000-0000-4000-8000-000000100452', '40000000-0000-4000-8000-000000010045', 'Trocar os limites de uma integral muda seu sinal.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010045', '$-x^2$', 'Quando a variável é o limite inferior, aumentar $x$ remove uma pequena faixa positiva da área acumulada. Por isso surge o sinal negativo.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100451', '40000000-0000-4000-8000-000000010045', 'Reescreva os limites', '$G(x)=-\int_4^x t^2,dt$.', 1), ('70000000-0000-4000-8000-000000100452', '40000000-0000-4000-8000-000000010045', 'Aplique o Teorema Fundamental', '$\frac d{dx}\int_4^x t^2,dt=x^2$.', 2), ('70000000-0000-4000-8000-000000100453', '40000000-0000-4000-8000-000000010045', 'Considere o sinal', '$G''(x)=-x^2$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010046', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $\int \frac{3x^2}{1+x^3},dx$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100461', '40000000-0000-4000-8000-000000010046', 'A', '$\ln|1+x^3|+C$', 1), ('50000000-0000-4000-8000-000000100462', '40000000-0000-4000-8000-000000010046', 'B', '$3\ln|1+x^3|+C$', 2), ('50000000-0000-4000-8000-000000100463', '40000000-0000-4000-8000-000000010046', 'C', '$1/(1+x^3)+C$', 3), ('50000000-0000-4000-8000-000000100464', '40000000-0000-4000-8000-000000010046', 'D', '$x^3/(1+x^3)+C$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010046', '50000000-0000-4000-8000-000000100461') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010046', '30000000-0000-4000-8000-000000000038', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100461', '40000000-0000-4000-8000-000000010046', 'O denominador tem derivada $3x^2$.', 1), ('60000000-0000-4000-8000-000000100462', '40000000-0000-4000-8000-000000010046', 'Use $u=1+x^3$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010046', '$\ln|1+x^3|+C$', 'Quando o numerador é a derivada do denominador, a substituição reduz a integral à forma $\int du/u$. O valor absoluto faz a fórmula valer nos intervalos permitidos.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100461', '40000000-0000-4000-8000-000000010046', 'Faça a substituição', '$u=1+x^3$ e $du=3x^2,dx$.', 1), ('70000000-0000-4000-8000-000000100462', '40000000-0000-4000-8000-000000010046', 'Reescreva a integral', 'Obtemos $\int\frac1u,du$.', 2), ('70000000-0000-4000-8000-000000100463', '40000000-0000-4000-8000-000000010046', 'Integre', '$\ln|u|+C=\ln|1+x^3|+C$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010047', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Qual é $\int_0^1 x^2,dx$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100471', '40000000-0000-4000-8000-000000010047', 'A', '$1/3$', 1), ('50000000-0000-4000-8000-000000100472', '40000000-0000-4000-8000-000000010047', 'B', '$1/2$', 2), ('50000000-0000-4000-8000-000000100473', '40000000-0000-4000-8000-000000010047', 'C', '$1$', 3), ('50000000-0000-4000-8000-000000100474', '40000000-0000-4000-8000-000000010047', 'D', '$0$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010047', '50000000-0000-4000-8000-000000100471') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010047', '30000000-0000-4000-8000-000000000036', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100471', '40000000-0000-4000-8000-000000010047', 'A primitiva de $x^2$ é $x^3/3$.', 1), ('60000000-0000-4000-8000-000000100472', '40000000-0000-4000-8000-000000010047', 'Use os dois limites.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010047', '$1/3$', 'A integral mede a área sob $x^2$ entre zero e um. A primitiva permite obter esse valor exato sem estimativa geométrica.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100471', '40000000-0000-4000-8000-000000010047', 'Integre', '$\int x^2,dx=x^3/3$.', 1), ('70000000-0000-4000-8000-000000100472', '40000000-0000-4000-8000-000000010047', 'Avalie em $1$', '$1^3/3=1/3$.', 2), ('70000000-0000-4000-8000-000000100473', '40000000-0000-4000-8000-000000010047', 'Avalie em $0$', '$0^3/3=0$, logo o resultado é $1/3$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010048', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Encontre uma primitiva de $f(x)=1/\sqrt{x}$, para $x>0$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100481', '40000000-0000-4000-8000-000000010048', 'A', '$2\sqrt{x}+C$', 1), ('50000000-0000-4000-8000-000000100482', '40000000-0000-4000-8000-000000010048', 'B', '$\sqrt{x}+C$', 2), ('50000000-0000-4000-8000-000000100483', '40000000-0000-4000-8000-000000010048', 'C', '$-2/\sqrt{x}+C$', 3), ('50000000-0000-4000-8000-000000100484', '40000000-0000-4000-8000-000000010048', 'D', '$\ln x+C$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010048', '50000000-0000-4000-8000-000000100481') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010048', '30000000-0000-4000-8000-000000000034', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100481', '40000000-0000-4000-8000-000000010048', 'Escreva $1/\sqrt{x}$ como $x^{-1/2}$.', 1), ('60000000-0000-4000-8000-000000100482', '40000000-0000-4000-8000-000000010048', 'Aumente o expoente para $1/2$ e divida pelo novo expoente.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010048', '$2\sqrt{x}+C$', 'Expoentes fracionários obedecem à mesma regra de potência. O coeficiente $2$ é necessário porque a derivada de $\sqrt{x}$ isolada teria apenas metade da taxa desejada.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100481', '40000000-0000-4000-8000-000000010048', 'Reescreva a potência', '$1/\sqrt{x}=x^{-1/2}$.', 1), ('70000000-0000-4000-8000-000000100482', '40000000-0000-4000-8000-000000010048', 'Integre pela regra da potência', '$x^{1/2}/(1/2)+C$.', 2), ('70000000-0000-4000-8000-000000100483', '40000000-0000-4000-8000-000000010048', 'Simplifique', '$2x^{1/2}+C=2\sqrt{x}+C$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010049', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'Calcule $\int_0^1 2x e^{x^2},dx$.')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100491', '40000000-0000-4000-8000-000000010049', 'A', '$e-1$', 1), ('50000000-0000-4000-8000-000000100492', '40000000-0000-4000-8000-000000010049', 'B', '$e$', 2), ('50000000-0000-4000-8000-000000100493', '40000000-0000-4000-8000-000000010049', 'C', '$1$', 3), ('50000000-0000-4000-8000-000000100494', '40000000-0000-4000-8000-000000010049', 'D', '$2e$', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010049', '50000000-0000-4000-8000-000000100491') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010049', '30000000-0000-4000-8000-000000000038', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100491', '40000000-0000-4000-8000-000000010049', 'Use $u=x^2$; os limites também devem mudar.', 1), ('60000000-0000-4000-8000-000000100492', '40000000-0000-4000-8000-000000010049', 'Quando $x=0$, $u=0$; quando $x=1$, $u=1$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010049', '$e-1$', 'A substituição funciona também em integrais definidas. Trocar os limites para a nova variável evita ter que retornar a $x$ antes de avaliar.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100491', '40000000-0000-4000-8000-000000010049', 'Substitua', '$u=x^2$ e $du=2x,dx$.', 1), ('70000000-0000-4000-8000-000000100492', '40000000-0000-4000-8000-000000010049', 'Atualize os limites', 'Os limites $0$ e $1$ continuam $0$ e $1$ para $u$.', 2), ('70000000-0000-4000-8000-000000100493', '40000000-0000-4000-8000-000000010049', 'Integre', '$\int_0^1e^u,du=e^u\big|_0^1=e-1$.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000010050', '20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'multiple_choice', 'medium', 'published', 'A velocidade é $v(t)=3t^2$ m/s. Qual deslocamento ocorre entre $t=0$ e $t=2$?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000100501', '40000000-0000-4000-8000-000000010050', 'A', '$8$ m', 1), ('50000000-0000-4000-8000-000000100502', '40000000-0000-4000-8000-000000010050', 'B', '$12$ m', 2), ('50000000-0000-4000-8000-000000100503', '40000000-0000-4000-8000-000000010050', 'C', '$6$ m', 3), ('50000000-0000-4000-8000-000000100504', '40000000-0000-4000-8000-000000010050', 'D', '$4$ m', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000010050', '50000000-0000-4000-8000-000000100501') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id, taxonomy_node_id, is_primary) values ('40000000-0000-4000-8000-000000010050', '30000000-0000-4000-8000-000000000036', true) on conflict (question_id, taxonomy_node_id) do update set is_primary = excluded.is_primary;
insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000100501', '40000000-0000-4000-8000-000000010050', 'Deslocamento é a integral da velocidade no tempo.', 1), ('60000000-0000-4000-8000-000000100502', '40000000-0000-4000-8000-000000010050', 'Calcule $\int_0^2 3t^2,dt$.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000010050', '$8$ m', 'Somar pequenas variações de posição ao longo do tempo equivale a integrar a velocidade. Como a velocidade é positiva, deslocamento e distância coincidem neste intervalo.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000100501', '40000000-0000-4000-8000-000000010050', 'Modele o deslocamento', '$\Delta s=\int_0^2 3t^2,dt$.', 1), ('70000000-0000-4000-8000-000000100502', '40000000-0000-4000-8000-000000010050', 'Encontre a primitiva', '$\int3t^2,dt=t^3$.', 2), ('70000000-0000-4000-8000-000000100503', '40000000-0000-4000-8000-000000010050', 'Avalie os limites', '$2^3-0^3=8$ m.', 3)
